result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "lockstep.py", "content": """"Lockstep determinism check: two simulated peers exchange state checksums.

Each peer runs an identical, fully deterministic simulation (seeded unit
movement + seeded combat rolls). Every TICKS_PER_CHECKPOINT ticks the peers
exchange a checksum of their full internal state (including RNG state) over
an in-memory queue. On mismatch, both peers halt and dump their state,
identifying the differing units.
"""

from __future__ import annotations

import hashlib
import json
import queue
import random
from dataclasses import dataclass, field

TICKS_PER_CHECKPOINT = 20
ARENA = 100.0
ATTACK_RANGE = 8.0


@dataclass
class Unit:
    uid: int
    x: float
    y: float
    hp: int
    heading: float
    target: int = -1


class Simulation:
    """A single deterministic simulation instance."""

    def __init__(self, seed: int, num_units: int = 12):
        self.peer_name = "?"
        self.seed = seed
        self.rng = random.Random(seed)
        self.tick = 0
        self.halted = False
        self.halt_reason: str | None = None
        self.units: list[Unit] = []
        self._spawn()

    # ---------------------------------------------------------------- setup
    def _spawn(self) -> None:
        rng = self.rng
        for i in range(len(DEFAULT_LAYOUT) if False else 0):
            pass  # placeholder; real spawn below
        for i in range(12 if not hasattr(self, "_num_units") else self._num_units):
            pass
        # Deterministic layout derived from the shared seed.
        for i in range(NUM_UNITS):
            self.units.append(
                Unit(
                    uid=i,
                    x=round(rng.uniform(0.0, ARENA), 6),
                    y=round(rng.uniform(0.0, ARENA), 6),
                    hp=rng.randint(80, 120),
                    heading=rng.uniform(0.0, 2.0 * 3.141592653589793),
                )
            )

    # ------------------------------------------------------------- stepping
    def step(self) -> None:
        """Advance one tick: movement jitter, then combat rolls."""
        assert not self.halted, "simulation halted"
        self.tick += 1
        rng = self.rng

        # Movement: seeded heading jitter + constant-speed advance, wall bounce.
        for u in self.units:
            u.heading += rng.uniform(-0.15, 0.15)
            u.x += 1.0 * _cos(u.heading)
            u.y += 1.0 * _sin(u.heading)
            if not (0.0 <= u.x <= ARENA):
                u.x = min(max(u.x, 0.0), ARENA)
                u.heading = 3.141592653589793 - u.heading
            if not (0.0 <= u.y <= ARENA):
                u.y = min(max(u.y, 0.0), ARENA)
                u.heading = -u.heading

        # Combat: nearest enemy within range takes a rolled hit.
        for u in self.units:
            tgt = self._nearest_enemy(u)
            u.target = tgt
            if tgt is None:
                continue
            dmg = rng.randint(1, 6)
            victim = self.units[tgt]
            victim.hp -= dmg
        # Cull dead units deterministically (lowest uid first).
        self.units = [u for u in self.units if u.hp > 0]

    def _nearest_enemy(self, u: Unit) -> int | None:
        best, best_d = None, ATTACK_RANGE**2
        for v in self.units:
            if v.uid == u.uid:
                continue
            d = (u.x - v.x) ** 2 + (u.y - v.y) ** 2
            if d <= best_d:
                best, best_d = v.uid, d
        return best

    # ------------------------------------------------------------ checksum
    def state_dict(self) -> dict:
        return {
            "tick": self.tick,
            "rng_state": _rng_to_json(self.rng),
            "units": [
                {
                    "uid": u.uid,
                    "x": round(u.x, 9),
                    "y": round(u.y, 9),
                    "hp": u.hp,
                    "heading": round(u.heading, 9),
                    "target": u.target,
                }
                for u in sorted(self.units, key=lambda u: u.uid)
            ],
        }

    def checksum(self) -> str:
        blob = json.dumps(self.state_dict(), sort_keys=True).encode()
        return hashlib.sha256(blob).hexdigest()


NUM_UNITS = 12


def _cos(x: float) -> float:
    import math

    return math.cos(x)


def _sin(x: float) -> float:
    import math

    return math.sin(x)


def _rng_to_json(rng: random.Random) -> list:
    st = rng.getstate()
    return [st[0], [int(v) for v in st[1]], st[2]]


# ------------------------------------------------------------------ harness
@dataclass
class DumpReport:
    halt_tick: int
    peers: tuple[str, str]
    differing_units: list[dict] = field(default_factory=list)

    def render(self) -> str:
        lines = [
            f"LOCKSTEP MISMATCH at tick {self.halt_tick} "
            f"({self.peers[0]} vs {self.peers[1]})",
            f"differing units: {len(self.differing_units)}",
        ]
        for d in self.differing_units:
            lines.append(
                f"  unit {d['uid']}: "
                + ", ".join(
                    f"{k}: A={d['a'][k]!r} B={d['b'][k]!r}" for k in d["fields"]
                )
            )
        return "\n".join(lines)


class LockstepPair:
    """Two peers in one process, checksum exchange over in-memory queues."""

    def __init__(self, seed: int, num_units: int = NUM_UNITS):
        self.peers = {
            "A": Simulation(seed, num_units),
            "B": Simulation(seed, num_units),
        }
        self.peers["A"].peer_name = "A"
        self.peers["B"].peer_name = "B"
        # A -> B and B -> A channels (in-memory).
        self.q_a_to_b: "queue.Queue[str]" = queue.Queue()
        self.q_b_to_a: "queue.Queue[str]" = queue.Queue()
        self.dump_report: DumpReport | None = None
        self.halt_tick: int | None = None

    @property
    def halted(self) -> bool:
        return any(p.halted for p in self.peers.values())

    def run(self, ticks: int, perturb=None) -> None:
        """Run up to `ticks` ticks. `perturb(tick, peer)` may mutate one peer."""
        for t in range(1, ticks + 1):
            if self.halted:
                return
            for p in self.peers.values():
                p.step()
            if perturb is not None:
                perturb(t)
            if t % TICKS_PER_CHECKPOINT == 0:
                self._exchange(t)
                if self.halted:
                    return

    def _exchange(self, t: int) -> None:
        a, b = self.peers["A"], self.peers["B"]
        cs_a, cs_b = a.checksum(), b.checksum()
        self.q_a_to_b.put(cs_a)
        self.q_b_to_a.put(cs_b)
        a_seen, b_seen = self.q_b_to_a.get(), self.q_a_to_b.get()

        ok = True
        if cs_a != a_seen:
            a.halted = b.halted = True
            a.halt_reason = f"peer A state != peer B's view of A (tick {t})"
            ok = False
        if cs_b != b_seen:
            a.halted = b.halted = True
            b.halt_reason = f"peer B state != peer A's view of B (tick {t})"
            ok = False
        if not ok:
            self.halt_tick = t
            self.dump_report = self._dump(t)

    def _dump(self, t: int) -> DumpReport:
        sa = self.peers["A"].state_dict()
        sb = self.peers["B"].state_dict()
        report = DumpReport(halt_tick=t, peers=("A", "B"))
        by_uid_b = {u["uid"]: u for u in sb["units"]}
        by_uid_a = {u["uid"]: u for u in sa["units"]}
        for uid in sorted(set(by_uid_a) | set(by_uid_b)):
            ua, ub = by_uid_a.get(uid), by_uid_b.get(uid)
            if ua is None or ub is None:
                report.differing_units.append(
                    {"uid": uid, "a": ua or {}, "b": ub or {},
                     "fields": ["<presence>"]}
                )
                continue
            fields = [k for k in ua if ua[k] != ub[k]]
            if fields:
                report.differing_units.append(
                    {"uid": uid, "a": ua, "b": ub, "fields": fields}
                )
        return report
